 const normalizeGrade=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\s_-]/g,'');const currentGrade=normalizeGrade(member?.role);const privileged=['admin','manager','patron','copatron','contremaitre'].includes(currentGrade);const available=articles.filter(a=>{if(a.active===false||a.data?.showInHarvest===false||/^(livraison|click\s*(?:&|and|et|n)?\s*collect)$/i.test(String(a.name||'').trim()))return false;if(['plateau','orange','sucre'].includes(String(a.name).toLowerCase().trim())&&!privileged)return false;const grades=a.data?.harvestGrades;if(Array.isArray(grades)&&grades.length&&!['admin','manager'].includes(currentGrade)&&!grades.some(g=>normalizeGrade(g)===currentGrade))return false;return true}).sort((a,b)=>{const ai=Number(a.data?.legacyId),bi=Number(b.data?.legacyId);if(Number.isFinite(ai)&&Number.isFinite(bi)&&ai>0&&bi>0)return ai-bi;if(Number.isFinite(ai)&&ai>0)return -1;if(Number.isFinite(bi)&&bi>0)return 1;return String(a.name).localeCompare(String(b.name),'fr')});
