 '<section class="panel harvest-history"><div class="section-heading"><div><span class="eyebrow">SUIVI DES RÉCOLTES</span><h3>Registre des récoltes</h3></div><span>'+h.length+' entrées</span></div><div class="scroll"><table><thead><tr><th>Date</th><th>Employé</th><th>Article</th><th>Quantité</th><th>Prime</th>'+(admin()?'<th>Actions</th>':'')+'</tr></thead><tbody>'+h.slice().reverse().map(x=>'<tr><td>'+esc(x.harvest_date||x.created_at?.slice(0,10))+'</td><td>'+esc(x.employee)+'</td><td>'+esc(x.product)+'</td><td><strong>'+esc(x.quantity)+'</strong></td><td>'+esc(cash(x.bonus_amount))+'</td>'+(admin()?'<td><button class="row-action edit-harvest" data-id="'+esc(x.id)+'" type="button">Modifier</button></td>':'')+'</tr>').join('')+'</tbody></table></div></section>';
 const chosen=new Map();
 const updateSummary=()=>{let total=0;const lines=[];for(const a of available){const n=chosen.get(String(a.id))||0;if(n){total+=n;lines.push('<div class="summary-line"><span>'+esc(a.name)+'</span><strong>× '+n+'</strong></div>')}}document.querySelector('#harvest-summary').innerHTML=lines.length?lines.join('')+'<div class="summary-total"><span>Unités à enregistrer</span><strong>'+total+'</strong></div>':'<p>Aucun produit sélectionné.</p>';document.querySelector('#save-harvest').disabled=!lines.length};
 el.querySelectorAll('.qty-plus,.qty-minus').forEach(btn=>btn.onclick=()=>{const id=btn.dataset.id,input=el.querySelector('.qty-input[data-id="'+id+'"]');const n=Math.max(0,Math.floor(Number(input.value)||0)+(btn.classList.contains('qty-plus')?1:-1));input.value=n;chosen.set(id,n);updateSummary()});
